parameters.functionCode:
const contact = $input.first().json;
const baseScore = 10;
let score = baseScore;

// Score berdasarkan kelengkapan data
if (contact.company) score += 5;
if (contact.job_title) score += 5;
if (contact.phone) score += 3;

// Score berdasarkan source
const sourceScores = {
  'website': 10,
  'referral': 15,
  'social': 5,
  'email': 8,
  'event': 12
};
score += sourceScores[contact.source] || 0;

return [{ json: { ...contact, calculated_score: score } }];

